describe('Complete Checkout Flow', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();
    cy.url().should('include', '/inventory.html');
  });

  it('should complete full checkout flow with valid information', () => {
    // Add backpack to cart
    cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('[data-test="remove-sauce-labs-backpack"]').should('be.visible');

    // Navigate to cart
    cy.get('.shopping_cart_link').click();
    cy.url().should('include', '/cart.html');
    cy.get('[data-test="inventory-item-name"]').should('contain', 'Sauce Labs Backpack');

    // Click checkout
    cy.get('[data-test="checkout"]').click();
    cy.url().should('include', '/checkout-step-one.html');

    // Fill checkout information
    cy.get('[data-test="firstName"]').type('Saif');
    cy.get('[data-test="lastName"]').type('Afzal');
    cy.get('[data-test="postalCode"]').type('201301');

    // Continue to overview
    cy.get('[data-test="continue"]').click();
    cy.url().should('include', '/checkout-step-two.html');

    // Verify overview page shows item total
    cy.get('[data-test="subtotal-label"]').should('be.visible');
    cy.get('[data-test="subtotal-label"]').should('contain', '$');

    // Complete order
    cy.get('[data-test="finish"]').click();
    cy.url().should('include', '/checkout-complete.html');

    // Verify confirmation
    cy.get('.complete-header').should('be.visible');
    cy.get('.complete-header').should('contain', 'Thank you for your order!');
  });

  it('should show validation error when postal code is missing', () => {
    // Add backpack to cart
    cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').click();

    // Navigate to cart and checkout
    cy.get('.shopping_cart_link').click();
    cy.get('[data-test="checkout"]').click();

    // Fill only first and last name
    cy.get('[data-test="firstName"]').type('Saif');
    cy.get('[data-test="lastName"]').type('Afzal');

    // Try to continue without postal code
    cy.get('[data-test="continue"]').click();

    // Verify error message appears
    cy.get('[data-test="error"]').should('be.visible');
    cy.get('[data-test="error"]').should('contain', 'Postal Code is required');

    // Verify still on checkout step one
    cy.url().should('include', '/checkout-step-one.html');
  });

  it('should handle multiple items in checkout', () => {
    // Add multiple items
    cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('[data-test="add-to-cart-sauce-labs-bike-light"]').click();

    // Navigate to cart
    cy.get('.shopping_cart_link').click();
    cy.get('[data-test="inventory-item"]').should('have.length', 2);

    // Proceed to checkout
    cy.get('[data-test="checkout"]').click();

    // Fill information
    cy.get('[data-test="firstName"]').type('Saif');
    cy.get('[data-test="lastName"]').type('Afzal');
    cy.get('[data-test="postalCode"]').type('201301');
    cy.get('[data-test="continue"]').click();

    // Verify both items on overview
    cy.get('[data-test="inventory-item-name"]').should('have.length', 2);
    cy.get('[data-test="subtotal-label"]').should('be.visible');

    // Complete order
    cy.get('[data-test="finish"]').click();
    cy.get('.complete-header').should('contain', 'Thank you for your order!');
  });
});
